use super::ImportSpec;

/// Render a module's `imports` field into TS import lines, one per entry, in the field's order.
pub fn render_import_block(imports: &[ImportSpec]) -> String {
    let mut out = String::new();
    for im in imports {
        let line = match im.kind.as_str() {
            "namespace" => format!(
                "import * as {} from \"{}\";",
                im.symbols.first().map(String::as_str).unwrap_or("_ns"),
                im.from
            ),
            "default" => format!(
                "import {} from \"{}\";",
                im.symbols.first().map(String::as_str).unwrap_or("_d"),
                im.from
            ),
            "side-effect" => format!("import \"{}\";", im.from),
            _ => {
                let kw = if im.type_only { "import type" } else { "import" };
                format!("{} {{ {} }} from \"{}\";", kw, im.symbols.join(", "), im.from)
            }
        };
        out.push_str(&line);
        out.push('\n');
    }
    out
}
